-- Study Abroad country content, BATCH 2: Ireland, France, Netherlands, New Zealand, United Arab Emirates.
-- Researched from public sources in November 2026 (see backend/TODO_country_tables.md for what still needs checking).
-- Text blocks fill the columns on countries; subject / course rows are linked to subjects / specializations
-- (country_sections.subject_id / specialization_id) so the website links them to those pages.
-- Replaces the earlier '[Sample]' / '[Placeholder]' rows of these 5 countries. Safe to re-run.
-- Requires alembic revision e6a3c9d1f4b7 (alembic upgrade head).
BEGIN;
DELETE FROM country_sections WHERE country_id IN (SELECT id FROM countries WHERE slug IN ('ireland', 'france', 'netherlands', 'new-zealand', 'united-arab-emirates'));
UPDATE countries SET why_title = 'Why study in Ireland?', why_body = '<p>Ireland is an English-speaking, safe and friendly country with a strong technology, pharmaceutical and finance sector. Trinity College Dublin is ranked 75th in the QS World University Rankings 2027, its strongest position in a decade.</p><ul><li>English-taught degrees across all levels</li><li>Home to European headquarters of many global technology and pharma companies</li><li>Graduate Scheme (Stamp 1G) lets you stay to look for work after your degree</li><li>Compact country: easy to travel between cities and to the rest of Europe</li></ul>', visa_title = 'Student visa requirements', visa_body = '<p>Students from visa-required countries apply online for a <strong>study visa</strong> after receiving an offer and paying tuition as requested. After arrival you register with immigration and receive a <strong>Stamp 2</strong> permission.</p><ul><li>Letter of acceptance from a recognised Irish institution, and proof of tuition payment where requested</li><li>Proof of funds: reported minimum of about €10,000 for the year (check the current rule on the Irish immigration service site)</li><li>Private medical insurance, passport, photographs and academic records</li><li>Work: Stamp 2 students may work up to 20 hours a week in term time and up to 40 hours in the permitted holiday periods</li><li>Graduate Scheme (Stamp 1G): up to 12 months after a Level 8 (Bachelor''s) degree and up to 24 months after a Level 9 or 10 (Master''s or PhD)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Irish immigration service (ISD) site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>Undergraduate applications generally go through the <strong>CAO</strong>; postgraduate applications are usually made directly to the university.</p><ul><li>Academic transcripts and certificates</li><li>Personal statement or statement of purpose</li><li>References for postgraduate applications</li><li>Proof of English proficiency</li><li>Passport copy</li><li>Portfolio or interview for some programmes</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Fees depend on the university and course. Dublin is the most expensive city for accommodation; other cities are cheaper.</p><ul><li>Tuition (non-EU): roughly €10,000-€25,000 a year for most courses; medicine and some health courses cost more</li><li>Living costs: about €10,000-€15,000 a year outside Dublin, higher in Dublin</li><li>Registration and student contribution charges may apply</li><li>Health insurance is required for non-EU students</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements differ by university and programme.</p><ul><li><strong>Bachelor''s:</strong> completed secondary school with strong results; some universities ask for a foundation year</li><li><strong>Master''s:</strong> a relevant bachelor''s degree, usually with a good second-class honours equivalent</li><li><strong>English:</strong> IELTS 6.0-6.5 for most undergraduate courses and 6.5 or higher for many Master''s; some universities accept TOEFL, PTE or Duolingo</li><li>Genuine intention to study full time and ability to pay</li></ul>' WHERE slug = 'ireland';
UPDATE countries SET why_title = 'Why study in France?', why_body = '<p>France has low public tuition fees, top universities and grandes écoles, and a strong industry base in aerospace, luxury, fashion, food and technology. Université PSL is ranked 34th in the QS World University Rankings 2027, the highest in France.</p><ul><li>Public university tuition is set by the state and is low compared with the UK and US</li><li>English-taught Master''s programmes in a growing number of subjects</li><li>Paris is a global centre for business, fashion, art and food</li><li>A residence permit lets you work part time and stay to look for a job after a Master''s</li></ul>', visa_title = 'Student visa requirements', visa_body = '<p>Students from outside the EU/EEA need a <strong>long-stay student visa (VLS-TS)</strong>. Many countries apply through <strong>Campus France</strong> (Études en France) before the visa interview.</p><ul><li>Admission letter or pre-enrolment from a French institution</li><li>Proof of funds: reported at €877.50 a month from 1 August 2026 (up from €615; some official pages still show €615, so confirm with the consulate)</li><li>Accommodation proof, health insurance and passport photos</li><li>Campus France interview where the procedure applies</li><li>Validation of the visa online within 3 months of arrival</li><li>Work: students may work up to 964 hours a year</li><li>After a Master''s: a temporary residence permit (APS) to look for work</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official France-Visas or Campus France site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>Most international students apply through <strong>Études en France</strong> (Campus France) for countries that use it, or directly to the university or school. Many business schools run their own admission process.</p><ul><li>Academic transcripts and certificates</li><li>Motivation letter and CV</li><li>French or English language proof</li><li>References for Master''s programmes</li><li>GMAT/GRE for some business programmes</li><li>Passport copy and Campus France file (where the procedure applies)</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Public universities charge low tuition set by the state; private schools and grandes écoles charge much more.</p><ul><li>Public university tuition for non-EU students: about €2,900 a year (Bachelor''s) and about €3,900 a year (Master''s) in recent years</li><li>Private schools and business schools: roughly €10,000-€35,000 a year</li><li>Living costs: higher in Paris; the visa guide is about €877.50 a month (reported)</li><li>Student health cover is provided through French social security</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Campus France site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the school and level.</p><ul><li><strong>Bachelor''s:</strong> completed secondary school equivalent to the French baccalauréat; some students need a foundation or language year first</li><li><strong>Master''s:</strong> a relevant bachelor''s degree (usually 3-4 years)</li><li><strong>Language:</strong> French B2 for French-taught courses (DELF, DALF, TCF or TEF); IELTS 6.0-6.5 or TOEFL 80+ for English-taught courses</li><li>Business schools may ask for GMAT or GRE and work experience</li></ul>' WHERE slug = 'france';
UPDATE countries SET why_title = 'Why study in the Netherlands?', why_body = '<p>The Netherlands offers one of the largest selections of English-taught programmes in continental Europe, with a focus on practical, project-based teaching. Dutch universities are strong in engineering, water management, agriculture and business.</p><ul><li>Over 2,000 English-taught programmes across universities and universities of applied sciences</li><li>Teaching based on group work and real projects</li><li>Orientation year (zoekjaar) for graduates to look for work</li><li>A central location for travel and careers in Europe</li></ul>', visa_title = 'Student visa requirements', visa_body = '<p>Most non-EU students need a <strong>residence permit for study</strong>. Your university normally applies to the Immigration and Naturalisation Service (<strong>IND</strong>) for you, and some students also need an <strong>MVV</strong> entry visa.</p><ul><li>Admission letter from a recognised Dutch institution</li><li>Proof of funds: the IND study norm is reported at about €1,180 a month for 2026 (changes each January), on top of tuition</li><li>IND fee: about €250 (reported as €243-€254, so check the IND site)</li><li>Valid passport, and a TB test for some nationalities</li><li>Work: students may work up to 16 hours a week, or full time in June, July and August</li><li>Orientation year (zoekjaar): up to 12 months after graduation to look for work or start a business</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official IND site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply through <strong>Studielink</strong> and the university''s own portal. Programmes with limited places (numerus fixus) have earlier deadlines.</p><ul><li>Academic transcripts and certificates</li><li>English proficiency proof</li><li>Motivation letter and CV</li><li>Letters of recommendation for some Master''s programmes</li><li>Passport copy</li><li>Portfolio or entrance test for some programmes</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Tuition for non-EU students depends on the programme and institution. Housing is the biggest living cost and is scarce in big cities.</p><ul><li>Tuition (non-EU): roughly €9,000-€20,000 a year, higher for some courses</li><li>Living costs: about €1,000-€1,200 a month; IND study norm is reported at about €1,180 (2026)</li><li>Housing in Amsterdam, Utrecht and Delft is limited, so start searching early</li><li>Health insurance is required in most cases</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Entry requirements depend on the university and the level.</p><ul><li><strong>Bachelor''s:</strong> secondary school diploma at the right level; many universities need specific subjects and may ask for a foundation year</li><li><strong>Master''s:</strong> a relevant bachelor''s degree with a good average, sometimes a language test and extra tests</li><li><strong>English:</strong> IELTS 6.0-6.5 or TOEFL 80-90, depending on the programme</li><li>Some universities of applied sciences ask for a minimum age or extra credit requirements</li></ul>' WHERE slug = 'netherlands';
UPDATE countries SET why_title = 'Why study in New Zealand?', why_body = '<p>New Zealand is known for safe campuses, small class sizes and strong support for international students. The University of Auckland is ranked 67th in the QS World University Rankings 2027, the highest in the country.</p><ul><li>Eight public universities, plus institutes of technology and polytechnics offering practical qualifications</li><li>Hands-on learning in agriculture, environment, engineering and health</li><li>Post-study work options for graduates</li><li>Safe, outdoor-focused lifestyle</li></ul>', visa_title = 'Student visa requirements', visa_body = '<p>International students need a <strong>Fee Paying Student visa</strong> from Immigration New Zealand (INZ), applied for online once you have an offer of place.</p><ul><li>Offer of place from an approved New Zealand institution</li><li>Financial support: reported at NZ$20,000 a year for living costs, plus tuition</li><li>Application fee: reported at about NZ$850 from 2026 (sources vary, so confirm with INZ)</li><li>Medical and police certificates where required</li><li>Work: about 20 hours a week in term time for most students; some sources report a rise to 25 hours, so confirm with INZ</li><li>Post-study work visa: up to 3 years for eligible degree graduates; new short-term graduate visas for some diploma graduates were announced for late 2026</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Immigration New Zealand site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to the university or institute, then to INZ for the visa.</p><ul><li>Academic transcripts and certificates</li><li>Proof of English proficiency</li><li>Personal statement or CV for postgraduate programmes</li><li>Passport copy</li><li>Portfolio for creative programmes</li><li>Proof of funds and a return ticket or evidence of funds for departure for the visa</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Fees depend on the university and programme. Auckland and Wellington are the most expensive cities.</p><ul><li>Tuition (international): roughly NZ$25,000-$45,000 a year for most undergraduate degrees; higher for medicine and veterinary courses</li><li>Living costs: INZ guide is NZ$20,000 a year</li><li>Visa fee: about NZ$850 (reported)</li><li>Health and travel insurance is required for the whole stay</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the institution and level.</p><ul><li><strong>Bachelor''s:</strong> completed secondary school with the required results; some applicants take a foundation course first</li><li><strong>Master''s:</strong> a relevant bachelor''s degree with a good grade average</li><li><strong>English:</strong> IELTS 6.0-6.5 for most degrees, 6.5-7.0 for some postgraduate courses (TOEFL, PTE and Cambridge are also accepted)</li><li>Good character requirements: police certificates and honest answers on the application</li></ul>' WHERE slug = 'new-zealand';
UPDATE countries SET why_title = 'Why study in the UAE?', why_body = '<p>The UAE is a fast-growing education hub with local universities and branch campuses of well-known international universities in Dubai and Abu Dhabi. Khalifa University is ranked 147th in the QS World University Rankings 2027.</p><ul><li>English-taught programmes and a very international student body</li><li>Branch campuses of foreign universities, often awarding the home university degree</li><li>Strong job market in business, hospitality, aviation, technology and engineering</li><li>Tax-free income for graduates who find work in the UAE</li></ul>', visa_title = 'Student visa requirements', visa_body = '<p>Most international students get a <strong>student residence visa</strong> sponsored by their university, which handles the application with the immigration authority.</p><ul><li>Admission letter from an accredited UAE institution</li><li>Passport, photographs and proof of funds or sponsor letter</li><li>Medical fitness test and health insurance</li><li>Emirates ID after arrival</li><li>Visa validity is usually 1 year, renewed with proof of enrolment</li><li>Work: part-time work needs a university NOC and a student work permit</li><li>Golden Visa: some outstanding graduates may qualify; check the official UAE portal for current criteria</li></ul><p><em>Reported total visa and processing costs range around AED 5,500-8,500 depending on the university.</em></p><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official UAE government (u.ae) and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>There is no central application: you apply to each university directly, often online.</p><ul><li>Academic transcripts and certificates, often attested</li><li>English proficiency result</li><li>Passport copy</li><li>Statement of purpose or CV for postgraduate courses</li><li>Entrance test or portfolio for some programmes</li><li>Check that the university and programme are accredited (CAA for federal licensing, KHDA in Dubai)</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Fees depend on the university; branch campuses of international universities are often among the more expensive.</p><ul><li>Tuition: roughly AED 30,000-100,000+ a year, depending on the university and course</li><li>Accommodation, food and transport: major cost, especially in Dubai</li><li>Visa and Emirates ID: reported at about AED 5,500-8,500 in total</li><li>Health insurance is mandatory</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and programme.</p><ul><li><strong>Bachelor''s:</strong> completed secondary school (equivalent to Grade 12) with the required marks, sometimes SAT/ACT or an entrance exam</li><li><strong>Master''s:</strong> a relevant bachelor''s degree, often with a GPA minimum</li><li><strong>English:</strong> IELTS 5.5-6.5 or equivalent (EmSAT for some UAE school applicants)</li><li>Applicants must usually be at least 18 for higher education visas</li></ul>' WHERE slug = 'united-arab-emirates';
COMMIT;
